import{_,o as a,c as t,a3 as r}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/94-在“缩小的世界”里不经意间筑起“傻瓜的围墙”.md","filePath":"books/xialiu-shehui/94-在“缩小的世界”里不经意间筑起“傻瓜的围墙”.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/94-在“缩小的世界”里不经意间筑起“傻瓜的围墙”.md"};function p(s,e,i,n,l,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="在-缩小的世界-里不经意间筑起-傻瓜的围墙" tabindex="-1">在“缩小的世界”里不经意间筑起“傻瓜的围墙” <a class="header-anchor" href="#在-缩小的世界-里不经意间筑起-傻瓜的围墙" aria-label="Permalink to &quot;在“缩小的世界”里不经意间筑起“傻瓜的围墙”&quot;">​</a></h2><p>在东京郊外相同的住宅区出生，在相同的中流家庭里长大，有着相同的价值观，这样的年轻人不断增加，缩小了与不同阶层的人发生碰撞的可能性，也就不太可能产生出新的文化，这就是所谓“世界缩小”了。</p><p>诚然，互联网使得相距遥远的地方也能在瞬间互通讯息，这在某种意义上是将广阔的世界缩小了。但与此同时，不可否认的是，互联网也使得人们减少了与他人见面的次数，还缩短了人们行动的半径，从而将真实的世界缩小了。换句话说，人们日常生活中的世界原本就已狭小，如今则面临着进一步缩小的危险。</p><p>简单一句话，那就是“井底之蛙”在不断增加。正如养老孟司在他的超级畅销书中所阐述的那样，互联网本是人们面向世界的一扇窗（Windows），但有时却也会形成一道“傻瓜的围墙”，因为只一味地相信世界由此真的变小了，而想不到它渐渐将人们与外面的世界隔绝了，岂不是傻瓜么？倘若人们只同与自己志趣相同的人来往，以为大家同属中流阶层，都是平等的，而将他人拒之门外，这样即便是在同一阶层中，也会不知不觉间进一步扩大阶层差距。</p><p>电影《楚门的世界》尖锐地批评了美国的郊外消费文化，主人公楚门乘坐的小船最后撞到的“海洋天堂”的墙正是“傻瓜的围墙”。人们生活在人工建造的舒适环境当中，从未觉察到自己周围的世界里存在着围墙，而围墙的外面才是真正的世界。</p><p>就像黑泽明的电影《天堂与地狱》中所描绘的，从“下只角”的河畔街道仰望山丘上的豪宅，会感受到社会的矛盾，引发对社会问题的思索，而那样的机会在一个人年轻的时候是十分必要的。</p><p>柏林墙是在一夜之间建成的，可正因为它真实地建在那里，任何人都会注意到它的存在，也就会对它采取处置的措施。如今这道“傻瓜的围墙”是在不知不觉间构筑起来的，它早已建成，却很少有人觉察到它的存在，只是沉溺于困在围墙内的舒适生活。这道“傻瓜的围墙”或许也会变成一道“下流的围墙”吧。</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',8)])])}const u=_(o,[["render",p]]);export{h as __pageData,u as default};
